// A video's date 0 ("not set", which MP4 counts from 1904) is no date (AVFoundation reports none; Android needed
// a check, CfNativeModule.parseVideoDate): the upload then takes the file's date. A real date is kept.
import Foundation
import Testing
@testable import CipherfilmCore

@Suite struct VideoDateTests {
  // 16x16, one frame, made with ffmpeg: one with creation time 0, one with 2021-06-15T10:00:00Z
  static let zero = ""
  static let dated = ""

  private func info(_ b64: String) async throws -> Media.Info {
    let url = FileManager.default.temporaryDirectory.appendingPathComponent("cf-video-\(UUID().uuidString).mp4")
    try Data(base64Encoded: b64)!.write(to: url)
    defer { try? FileManager.default.removeItem(at: url) }
    return await Media.info(url, video: true)
  }

  @Test func zeroDateIsNoDate() async throws {
    #expect(try await info(Self.zero).captureTs == nil)
  }

  @Test func realDateIsKept() async throws {
    #expect(try await info(Self.dated).captureTs == 1_623_751_200_000)
  }
}
